#!/bin/bash
# fix-card-render-quality-v1.sh
#
# Three real bugs fixed, each verified against actual generated PDFs:
#
#   1. GUILLOCHE LINES MISSING ON BACK: the back card's wave-line pattern
#      referenced a <pattern> defined only inside the front card's SVG.
#      Since front and back get captured as two separate images for the
#      PDF, the back lost access to that shared definition entirely.
#      Fixed by giving the back its own self-contained pattern.
#
#   2. MICROPRINT RING TOO BOLD: the 50% fade was applied via CSS opacity
#      on the container, which wasn't surviving the PDF capture reliably.
#      Fixed by baking the fade directly into the image's alpha channel
#      instead -- can't be dropped by any capture process.
#
#   3. BLURRINESS AT HIGH ZOOM: increased html2canvas capture resolution
#      (scale 4 -> 6) and regenerated the ring image at higher resolution
#      with supersampling for cleaner edges.
#
# Creates portal/assets/microring.png and overwrites portal/id-card-view.html.
# Safe to re-run.

set -e

echo "==> Creating portal/assets/microring.png"
mkdir -p portal/assets
base64 -d > portal/assets/microring.png << 'B64_EOF'
